from __future__ import annotations

from fastapi import FastAPI
from fastapi.responses import HTMLResponse


PAPER_DASHBOARD_HTML = r"""
<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>BTC 5m Event Prediction Paper</title><style>
:root{color-scheme:dark;--bg:#07111f;--panel:#10213a;--line:#2a405e;--text:#eef5ff;--muted:#9fb2cc;--good:#2ed573;--bad:#ff6b6b;--wait:#f6c344;--blue:#52b7ff}*{box-sizing:border-box}body{margin:0;background:linear-gradient(180deg,#07111f,#091729 48%,#07111f);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.wrap{max-width:980px;margin:auto;padding:16px 14px 32px}.top{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.eyebrow{font-size:12px;color:var(--muted);letter-spacing:.14em;text-transform:uppercase}.title{font-size:25px;font-weight:900;margin:4px 0}.sub{color:var(--muted);font-size:14px}.pill{border:1px solid var(--line);padding:8px 12px;border-radius:999px;font-weight:800;font-size:12px;background:#0c1b31;white-space:nowrap}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:12px;margin-top:14px}.card{grid-column:span 12;background:rgba(16,33,58,.95);border:1px solid var(--line);border-radius:18px;padding:14px;box-shadow:0 10px 30px rgba(0,0,0,.16)}.mini{grid-column:span 6}.third{grid-column:span 4}.quarter{grid-column:span 3}.label{color:var(--muted);font-size:13px}.value{font-size:30px;font-weight:900;margin-top:4px}.smallvalue{font-size:21px;font-weight:850;margin-top:4px}.row{display:flex;justify-content:space-between;gap:12px;padding:9px 0;border-bottom:1px solid rgba(159,178,204,.16)}.row:last-child{border-bottom:0}.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px;overflow-wrap:anywhere}.good{color:var(--good)}.bad{color:var(--bad)}.wait{color:var(--wait)}.blue{color:var(--blue)}.source{display:grid;grid-template-columns:1.3fr .7fr .7fr;gap:8px;padding:9px 0;border-bottom:1px solid rgba(159,178,204,.16)}.bar{height:8px;background:#0b1728;border-radius:999px;overflow:hidden;margin-top:10px}.fill{height:100%;width:50%;background:linear-gradient(90deg,#2ed573,#52b7ff);transition:width .3s}.links a{color:#b9e6ff;text-decoration:none;margin-right:10px;display:inline-block;margin-top:8px}.hint{color:var(--muted);font-size:12px;margin-top:6px}.stamp{color:var(--muted);font-size:12px;text-align:right;margin-top:10px}@media(max-width:720px){.mini,.third,.quarter{grid-column:span 12}.title{font-size:21px}.value{font-size:27px}}
</style></head><body><main class="wrap"><header class="top"><div><div class="eyebrow">Polymarket · BTC 5 Minute</div><div class="title">Event Prediction Paper 儀表板</div><div class="sub">AI 判斷 BTC 五分鐘漲跌 · Paper 模擬持倉 · 真實下單關閉</div></div><div id="systemPill" class="pill">LOADING</div></header><section class="grid">
<article class="card mini"><div class="label">AI 判斷</div><div id="direction" class="value wait">WAIT</div><div id="decisionHint" class="hint">等待市場與資料來源同步</div></article><article class="card mini"><div class="label">距離本輪結束</div><div id="countdown" class="value">--:--</div><div class="hint">依目前 BTC 5 分鐘市場估算</div></article>
<article class="card third"><div class="label">上漲機率</div><div id="probability" class="smallvalue">—</div><div class="bar"><div id="probabilityBar" class="fill"></div></div></article><article class="card third"><div class="label">AI 信心</div><div id="confidence" class="smallvalue">—</div></article><article class="card third"><div class="label">最佳 Edge</div><div id="selectedEdge" class="smallvalue">—</div></article>
<article class="card quarter"><div class="label">已實現 PnL</div><div id="realizedPnl" class="smallvalue">$0.0000</div></article><article class="card quarter"><div class="label">未實現 PnL</div><div id="unrealizedPnl" class="smallvalue">$0.0000</div></article><article class="card quarter"><div class="label">持倉數</div><div id="openPositions" class="smallvalue">0</div></article><article class="card quarter"><div class="label">Paper 勝率</div><div id="winRate" class="smallvalue">0.00%</div><div id="winRecord" class="hint">勝 0 · 負 0 · 平 0 · 樣本 0</div></article>
<article class="card mini"><h3>盤面價格</h3><div class="row"><span>YES Ask</span><strong id="yesAsk">—</strong></div><div class="row"><span>NO Ask</span><strong id="noAsk">—</strong></div><div class="row"><span>YES Edge</span><strong id="yesEdge">—</strong></div><div class="row"><span>NO Edge</span><strong id="noEdge">—</strong></div></article><article class="card mini"><h3>目前市場</h3><div class="row"><span>發現狀態</span><strong id="discovery">—</strong></div><div class="row"><span>Slug</span><strong id="slug" class="mono">—</strong></div><div class="row"><span>問題</span><strong id="question" class="mono">—</strong></div></article>
<article class="card mini"><h3>Paper 執行</h3><div class="row"><span>模擬下單</span><strong id="paperOrders">ON</strong></div><div class="row"><span>持倉模擬</span><strong id="paperPositions">ON</strong></div><div class="row"><span>提交筆數</span><strong id="submitted">0</strong></div><div class="row"><span>拒絕筆數</span><strong id="rejected">0</strong></div><div class="row"><span>Queue</span><strong id="queue">0</strong></div><div class="row"><span>已平倉</span><strong id="closedTrades">0</strong></div></article><article class="card mini"><h3>安全模式</h3><div class="row"><span>執行模式</span><strong id="execution">paper_simulation</strong></div><div class="row"><span>真實下單</span><strong id="liveOrders">OFF</strong></div><div class="row"><span>錢包簽名</span><strong id="wallet">OFF</strong></div><div class="row"><span>Live Trading</span><strong id="liveTrading">OFF</strong></div><div class="row"><span>一般事件掃描</span><strong id="scanner">OFF</strong></div></article>
<article class="card mini"><h3>資料來源</h3><div id="sources"><div class="hint">尚未取得來源狀態</div></div></article><article class="card mini"><h3>目前持倉</h3><pre id="positions" class="mono">[]</pre></article><article class="card"><h3>Fusion 狀態</h3><pre id="fusion" class="mono">{}</pre><div class="links"><a href="/status">/status</a><a href="/mode">/mode</a><a href="/paper/status">/paper/status</a><a href="/paper/winrate">/paper/winrate</a><a href="/healthz">/healthz</a><a href="/docs">/docs</a></div><div id="updated" class="stamp">尚未更新</div></article>
</section></main><script>
const $=id=>document.getElementById(id);const pct=x=>Number.isFinite(Number(x))?`${(Number(x)*100).toFixed(2)}%`:'—';const price=x=>Number.isFinite(Number(x))?Number(x).toFixed(4):'—';const usd=x=>Number.isFinite(Number(x))?`$${Number(x).toFixed(4)}`:'—';const boolText=x=>x?'ON':'OFF';function directionClass(d){return d==='YES'?'good':d==='NO'?'bad':'wait'}function calcCountdown(c){const now=Math.floor(Date.now()/1000);let start=Number(c?.interval_start||0);if(!start){const m=String(c?.slug||'').match(/(\d{10})$/);if(m)start=Number(m[1])}if(!start)return'--:--';const r=Math.max(0,start+300-now);return`${String(Math.floor(r/60)).padStart(2,'0')}:${String(r%60).padStart(2,'0')}`}function sourceRows(s){const e=Object.entries(s||{});if(!e.length)return'<div class="hint">尚未取得來源狀態</div>';return e.map(([n,v])=>`<div class="source"><strong>${n}</strong><span class="${v.connected?'good':'bad'}">${v.connected?'ONLINE':'OFFLINE'}</span><span>${Number.isFinite(Number(v.age_ms))?Math.round(Number(v.age_ms))+' ms':'—'}</span></div>`).join('')}async function refresh(){try{const [s,m]=await Promise.all([fetch('/status',{cache:'no-store'}).then(r=>r.json()),fetch('/mode',{cache:'no-store'}).then(r=>r.json())]);const ai=s.ai||{},market=s.market||{},current=market.current||{},paper=s.paper||{},sum=paper.summary||{},metrics=s.execution_metrics||{},safe=m.safety||{};const d=ai.direction||'WAIT';$('direction').textContent=d;$('direction').className=`value ${directionClass(d)}`;$('decisionHint').textContent=d==='WAIT'?'等待信心、Edge、深度與風控條件':`目前偏向 ${d}`;$('countdown').textContent=calcCountdown(current);$('probability').textContent=pct(ai.probability_up);$('probabilityBar').style.width=`${Math.max(0,Math.min(100,Number(ai.probability_up||.5)*100))}%`;$('confidence').textContent=pct(ai.confidence);$('selectedEdge').textContent=pct(ai.selected_edge);$('yesAsk').textContent=price(market.yes_ask);$('noAsk').textContent=price(market.no_ask);$('yesEdge').textContent=pct(ai.yes_edge);$('noEdge').textContent=pct(ai.no_edge);$('discovery').textContent=market.discovery_status||'—';$('slug').textContent=current.slug||'—';$('question').textContent=current.question||'—';$('realizedPnl').textContent=usd(sum.realized_pnl||0);$('unrealizedPnl').textContent=usd(sum.unrealized_pnl||0);$('openPositions').textContent=sum.open_positions||0;$('winRate').textContent=pct(sum.win_rate||0);$('winRecord').textContent=`勝 ${sum.wins||0} · 負 ${sum.losses||0} · 平 ${sum.flat||0} · 樣本 ${sum.closed_trades||0}`;$('submitted').textContent=metrics.orders_submitted||0;$('rejected').textContent=metrics.orders_rejected||0;$('queue').textContent=metrics.queue_depth||0;$('closedTrades').textContent=sum.closed_trades||0;$('paperOrders').textContent=boolText(safe.paper_orders_enabled);$('paperPositions').textContent=boolText(safe.paper_positions_enabled);$('liveOrders').textContent=boolText(safe.live_orders_enabled);$('wallet').textContent=boolText(safe.wallet_signing_enabled);$('liveTrading').textContent=boolText(safe.live_trading_enabled);$('scanner').textContent=boolText(safe.general_event_scanner_enabled);$('execution').textContent=m.execution||'—';$('sources').innerHTML=sourceRows(s.sources);$('positions').textContent=JSON.stringify(paper.open_positions||[],null,2);$('fusion').textContent=JSON.stringify(s.fusion||{},null,2);const active=market.discovery_status==='ready';$('systemPill').textContent=active?'SYSTEM ACTIVE':'WAITING';$('systemPill').className=`pill ${active?'good':'wait'}`;$('updated').textContent=`更新時間 ${new Date().toLocaleTimeString()}`}catch(e){$('systemPill').textContent='OFFLINE';$('systemPill').className='pill bad';$('updated').textContent=`讀取失敗 ${new Date().toLocaleTimeString()}`}}refresh();setInterval(refresh,1500)
</script></body></html>
"""


def register_btc5m_event_paper_ui(app: FastAPI) -> None:
    @app.get("/ui", response_class=HTMLResponse)
    async def dedicated_paper_ui() -> HTMLResponse:
        return HTMLResponse(PAPER_DASHBOARD_HTML)
